function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'DataStream' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with DataStream(value, k).';
  const [value, k] = args[0];
  if (!Number.isInteger(value) || value < 1 || value > 1e9) return 'value is between 1 and 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1e5) return 'k is between 1 and 10^5.';
  if (operations.length - 1 > 1e5) return 'At most 10^5 calls to consec.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'consec') return 'Only consec can follow the constructor.';
    if (!Array.isArray(args[i]) || args[i].length !== 1) return 'consec takes one integer.';
    const num = args[i][0];
    if (!Number.isInteger(num) || num < 1 || num > 1e9) return 'num is between 1 and 10^9.';
  }
  return null;
}

