class DataStream {
  constructor(value, k) {
    this.value = value;
    this.k = k;
    this.stream = [];
  }
  consec(num) {
    this.stream.push(num);
    if (this.stream.length < this.k) return false;
    return this.stream.slice(this.stream.length - this.k).every(x => x === this.value);
  }
}

