function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const value = large ? pick(1, 1e9) : pick(1, 4);
  let k;
  if (large) {
    const shape = rand();
    k = shape < 0.15 ? pick(400, 100000) : shape < 0.4 ? pick(1, 5) : pick(5, 200);
  } else {
    k = pick(1, 5);
  }
  const calls = large ? 499 : pick(1, 15);
  // Draw the stream in runs so that long stretches of value appear often enough to reach k.
  const other = () => {
    if (!large) return pick(1, 4);
    const x = pick(1, 1e9);
    return x === value ? (value === 1 ? 2 : value - 1) : x;
  };
  const operations = ['DataStream'];
  const args = [[value, k]];
  while (operations.length - 1 < calls) {
    const runLength = large ? pick(1, Math.min(2 * k + 3, 300)) : pick(1, 6);
    const hit = rand() < 0.7;
    for (let i = 0; i < runLength && operations.length - 1 < calls; i++) {
      operations.push('consec');
      args.push([hit ? value : other()]);
    }
  }
  return [operations, args];
}
